query PinterestBaselineOrders($first: Int!, $after: String, $query: String!) {
  orders(first: $first, after: $after, query: $query) {
    nodes {
      id
      createdAt
      test
      cancelledAt
      displayFinancialStatus
      customerJourneySummary {
        ready
        firstVisit { source sourceType utmParameters { source medium campaign content } }
        lastVisit { source sourceType utmParameters { source medium campaign content } }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}
